"""Checks the NumPy port against tests/golden.json (generated by the JS reference).

    python -m pytest python/test_golden.py -q
"""
import json
import math
import pathlib
import sys

import numpy as np
import pytest

HERE = pathlib.Path(__file__).resolve().parent
sys.path.insert(0, str(HERE))
import ltem_optics as O  # noqa: E402

GOLDEN = json.loads((HERE.parent / "tests" / "golden.json").read_text(encoding="utf-8"))
TOL = GOLDEN["tolerance"]
CASES = list(GOLDEN["cases"].items())


def _close(a, b, rel, abs_):
    return abs(a - b) <= max(abs_, rel * max(abs(a), abs(b)))


def _cmp(path, got, exp, rel, abs_, errors):
    if exp is None:
        if got is not None:
            errors.append(f"{path}: expected None, got {got!r}")
        return
    if isinstance(exp, bool) or isinstance(exp, str):
        if got != exp:
            errors.append(f"{path}: got {got!r}, expected {exp!r}")
        return
    if isinstance(exp, (int, float)):
        if not isinstance(got, (int, float, np.floating, np.integer)) or not _close(float(got), float(exp), rel, abs_):
            errors.append(f"{path}: got {got!r}, expected {exp!r}")
        return
    if isinstance(exp, list):
        for i, e in enumerate(exp):
            _cmp(f"{path}[{i}]", got[i] if got is not None and i < len(got) else None, e, rel, abs_, errors)
        return
    for k, e in exp.items():
        _cmp(f"{path}.{k}", got.get(k) if isinstance(got, dict) else None, e, rel, abs_, errors)


def _summary(s):
    return {
        "M": s["M"], "W": s["W"], "N": s["N"], "nr": s["nr"], "rel": s["rel"], "peak": s["peak"], "IperP": s["IperP"],
        "fwhmL": s["fwhmL"], "fwhmS": s["fwhmS"], "ang": s["ang"], "area": s["area"], "peakAt": s["peakAt"],
        "cx": s["cx"], "cy": s["cy"], "border": s["border"], "x0_mm": s["x0"], "I_sum": float(np.sum(s["I"].astype(np.float64))),
        "halfmax_segments": int(O.contour(s, 0.5 * s["peak"]).shape[0]),
    }


@pytest.mark.parametrize("name,case", CASES, ids=[c[0] for c in CASES])
def test_beam_diameter(name, case):
    p = O.resolve_params(case["params_in"])
    assert abs(p["D"] - case["params_resolved"]["D"]) <= TOL["D_abs_mm"]
    assert abs(O.optimal_beam_diameter(p) - case["optimal_D_mm"]) <= 1e-6


@pytest.mark.parametrize("name,case", CASES, ids=[c[0] for c in CASES])
def test_steering_response(name, case):
    p = O.resolve_params(case["params_in"])
    errors = []
    for r in case["responses"]:
        got = O.steering_response(p, r["yaw_um"], r["pitch_um"])
        _cmp(f"{name}.response({r['yaw_um']},{r['pitch_um']})", got, r["result"], 1e-9, TOL["response_abs_um"], errors)
    assert not errors, "\n".join(errors[:20])


@pytest.mark.parametrize("name,case", CASES, ids=[c[0] for c in CASES])
def test_spot_shape(name, case):
    p = O.resolve_params(case["params_in"])
    errors = []
    for s in case["spots"]:
        got = O.spot_shape(p, s["yaw_um"], s["pitch_um"], s["quality"])
        exp = dict(s["result"])
        samples = exp.pop("I_samples")
        tag = f"{name}.spot({s['yaw_um']},{s['pitch_um']},{s['quality']})"
        _cmp(tag, _summary(got), exp, TOL["spot_rel"], TOL["spot_abs"], errors)
        for smp in samples:
            _cmp(f"{tag}.I[{smp['row']},{smp['col']}]", float(got["I"][smp["row"], smp["col"]]), smp["value"], TOL["spot_rel"], 1e-9, errors)
    assert not errors, "\n".join(errors[:20])


@pytest.mark.parametrize("name,case", CASES, ids=[c[0] for c in CASES])
def test_peak_curves(name, case):
    p = O.resolve_params(case["params_in"])
    errors = []
    for ax in ("yaw", "pitch"):
        travels = [o["travel_um"] for o in case["curves"][ax]]
        _cmp(f"{name}.curve.{ax}", O.peak_curve(p, ax, travels, "trend"), case["curves"][ax], TOL["curve_rel"], TOL["spot_abs"], errors)
    assert not errors, "\n".join(errors[:20])


def test_physical_sanity():
    """Independent checks that do not rely on the golden file."""
    p = O.resolve_params({})
    r = O.steering_response(p, 1.0, 0.0)
    # analytic small-angle result for the horizontal actuator: Δx = 2R·Δ/L (Δ = 1 µm)
    assert math.isclose(-r["perUm"]["yaw"][0], 2 * p["R"] / p["L"], rel_tol=2e-3)
    th, be = math.radians(p["theta"]), math.radians(p["beta"])
    dy_expected = 2 * p["R"] / p["L"] * math.sin(th) * math.sin(be) / (1 + math.sin(th) * math.cos(be))
    assert math.isclose(-r["perUm"]["yaw"][1], dy_expected, rel_tol=5e-3)
    assert r["yawTurnsBeamToFront"] is True
    # the aligned spot is diffraction limited: peak ≈ 1 (Strehl) and centred on the chief ray
    s0 = O.spot_shape(p, 0, 0)
    assert s0["peak"] > 0.99 and math.hypot(*s0["peakAt"]) < 0.05
    # long axis of the aligned spot lies along the plane of incidence and is ≈ 1/cosθ longer
    inc = math.atan2(r["incidencePlane"][1], r["incidencePlane"][0])
    d = (math.degrees(s0["ang"] - inc) + 90) % 180 - 90
    assert abs(d) < 3
    assert 1.7 < s0["fwhmL"] / s0["fwhmS"] < 2.3


def test_results_do_not_alias_caches():
    """Mutating a returned spot must not change later results (the aligned spot is cached internally)."""
    p = O.resolve_params({})
    a = O.spot_shape(p, 0, 0)
    a["I"][:] = 0
    a["x0"][0] = 1e9
    b = O.spot_shape(p, 0, 0)
    assert float(b["I"].max()) > 0.9 and abs(b["x0"][0]) < 1
    assert O.resolve_params({})["D"] == p["D"]  # D='auto' is cached per parameter set
